  if (value === Infinity) {
    throw new Error('Out of range float values are not JSON compliant: inf');
  }
  if (value === -Infinity) {
    throw new Error('Out of range float values are not JSON compliant: -inf');
  }
  return pyFloatRepr(value);
}

