export function pyBytesRepr(s) {
  const hasSingle = s.includes("'");
  const hasDouble = s.includes('"');
  const quote = hasSingle && !hasDouble ? '"' : "'";

  let body = '';
  for (const ch of s) {
    const code = ch.codePointAt(0);
    if (code >= 0x20 && code < 0x7f) {
      if (ch === '\\') {
        body += '\\\\';
      } else if (ch === quote) {
        body += '\\' + quote;
      } else {
        body += ch;
      }
    } else if (ch === '\n') {
      body += '\\n';
    } else if (ch === '\r') {
      body += '\\r';
    } else if (ch === '\t') {
      body += '\\t';
    } else {
      body += '\\x' + code.toString(16).padStart(2, '0');
    }
  }

  return 'b' + quote + body + quote;
}

