// Python float semantics: parsing (float(str)) and repr(float).

export class FloatParseError extends Error {
  constructor(input) {
    super(`could not convert string to float: '${input}'`);
    this.name = 'FloatParseError';
    this.input = input;
  }
}

const FLOAT_RE =
  /^[+-]?((\d(_?\d)*)?\.\d(_?\d)*|(\d(_?\d)*\.?))([eE][+-]?\d(_?\d)*)?$/;

export function parsePyFloat(str) {
  const s = String(str).trim();
  const m = /^([+-]?)(inf(inity)?|nan)$/i.exec(s);
  if (m) {
    if (m[2].toLowerCase() === 'nan') return NaN;
    return m[1] === '-' ? -Infinity : Infinity;
  }
  if (!FLOAT_RE.test(s)) throw new FloatParseError(str);
  return Number(s.replace(/_/g, ''));
}

export function pyFloatRepr(x) {
  if (Number.isNaN(x)) return 'nan';
  if (x === Infinity) return 'inf';
  if (x === -Infinity) return '-inf';
  const neg = x < 0 || Object.is(x, -0);
  const a = Math.abs(x);
  let out;
  if (a === 0) {
    out = '0.0';
  } else {
    // Shortest round-trip digits via toExponential() with no argument.
    const s = a.toExponential(); // e.g. '1.2345678912345679e+8'
    const eIdx = s.indexOf('e');
    const digits = s.slice(0, eIdx).replace('.', '');
    const e = parseInt(s.slice(eIdx + 1), 10);
    const decpt = e + 1;
    if (decpt <= -4 || decpt > 16) {
      let body = digits[0];
      if (digits.length > 1) body += '.' + digits.slice(1);
      const exp = decpt - 1;
      const sign = exp < 0 ? '-' : '+';
      const absExp = String(Math.abs(exp)).padStart(2, '0');
      out = body + 'e' + sign + absExp;
    } else if (decpt <= 0) {
      out = '0.' + '0'.repeat(-decpt) + digits;
    } else if (decpt >= digits.length) {
      out = digits + '0'.repeat(decpt - digits.length) + '.0';
    } else {
      out = digits.slice(0, decpt) + '.' + digits.slice(decpt);
    }
  }
  return neg ? '-' + out : out;
}

