import { parsePyFloat, FloatParseError } from './pyfloat.mjs';

// argparse's negative-number matcher: tokens like '-5', '-3.14', '-.5' are
// treated as values, not option strings.
const NEGATIVE_NUMBER = /^-\d+$|^-\d*\.\d+$/;

function looksLikeOptionString(token) {
  if (token === '-') return false;
  if (!token.startsWith('-')) return false;
  return !NEGATIVE_NUMBER.test(token);
}

function usageLine(prog) {
  return `usage: ${prog} [-h] --a A`;
}

function fail(prog, message) {
  process.stderr.write(usageLine(prog) + '\n');
  process.stderr.write(`${prog}: error: ${message}\n`);
  process.exit(2);
}

function printHelp(prog) {
  process.stdout.write(
    usageLine(prog) + '\n' +
    '\n' +
    'options:\n' +
    '  -h, --help  show this help message and exit\n' +
    '    --a A\n'
  );
  process.exit(0);
}

// Python repr() of a string, using single quotes.
function pyStringRepr(value) {
  let out = "'";
  for (const ch of value) {
    const cp = ch.codePointAt(0);
    if (ch === "'" || ch === '\\') {
      out += '\\' + ch;
    } else if (ch === '\n') {
      out += '\\n';
    } else if (ch === '\r') {
      out += '\\r';
    } else if (ch === '\t') {
      out += '\\t';
    } else if (cp >= 0x20 && cp < 0x7f) {
      out += ch;
    } else if (cp <= 0xff) {
      out += '\\x' + cp.toString(16).padStart(2, '0');
    } else if (cp <= 0xffff) {
      out += '\\u' + cp.toString(16).padStart(4, '0');
    } else {
      out += '\\U' + cp.toString(16).padStart(8, '0');
    }
  }
  return out + "'";
}

export function parseArgs(argv, prog) {
  let a;
  let hasA = false;
  const unrecognized = [];

  let i = 0;
  while (i < argv.length) {
    const token = argv[i];
    if (token === '-h' || token === '--help') {
      printHelp(prog);
    } else if (token === '--a' || token.startsWith('--a=')) {
      let raw;
      if (token === '--a') {
        const next = argv[i + 1];
        if (next === undefined || looksLikeOptionString(next)) {
          fail(prog, 'argument --a: expected one argument');
        }
        raw = next;
        i += 1;
      } else {
        raw = token.slice('--a='.length);
      }
      try {
        a = parsePyFloat(raw);
      } catch (err) {
        if (err instanceof FloatParseError) {
          fail(prog, `argument --a: invalid float value: ${pyStringRepr(raw)}`);
        }
        throw err;
      }
      hasA = true;
    } else {
      unrecognized.push(token);
    }
    i += 1;
  }

  if (!hasA) {
    fail(prog, 'the following arguments are required: --a');
  }
  if (unrecognized.length > 0) {
    fail(prog, `unrecognized arguments: ${unrecognized.join(' ')}`);
  }
  return { a };
}

